import requests
import sseclient
import threading
import json
import time
from urllib.parse import urljoin

class MCPClient:
    def __init__(self, url):
        self.url = url
        self.post_url = None
        self.msg_id = 1
        self.responses = {}
        self.events = []

    def connect(self):
        self.session_response = requests.get(self.url, headers={'Accept': 'text/event-stream'}, stream=True)
        self.client = sseclient.SSEClient(self.session_response)

        def listen():
            for event in self.client.events():
                if event.event == 'endpoint':
                    self.post_url = urljoin(self.url, event.data)
                elif event.event == 'message':
                    try:
                        data = json.loads(event.data)
                        if 'id' in data:
                            self.responses[data['id']] = data
                        else:
                            self.events.append(data)
                    except:
                        pass
        self.t = threading.Thread(target=listen, daemon=True)
        self.t.start()
        time.sleep(1)

    def call_tool(self, name, args):
        if not self.post_url:
            raise Exception("Not connected")
        req_id = self.msg_id
        self.msg_id += 1
        req = {
            "jsonrpc": "2.0",
            "id": req_id,
            "method": "tools/call",
            "params": {
                "name": name,
                "arguments": args
            }
        }
        res = requests.post(
            self.post_url,
            headers={'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream'},
            json=req
        )
        if res.status_code not in (200, 202):
            print("Error POSTing:", res.status_code, res.text)

        for _ in range(50):
            if req_id in self.responses:
                return self.responses.pop(req_id)
            time.sleep(0.1)
        return {"error": "timeout"}

if __name__ == "__main__":
    client = MCPClient("http://are-sidecar:8000/mcp")
    client.connect()
    print("POST URL:", client.post_url)
    res = client.call_tool("AgentUserInterface__get_last_message_from_user", {})
    print("Response:")
    print(json.dumps(res, indent=2))
EOF

