import requests
import json
import sseclient
import sys

url = "http://are-sidecar:8000/mcp"

res = requests.head(url)
sid = res.headers.get("mcp-session-id")

headers = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/event-stream",
    "mcp-session-id": sid
}

def send_req(payload):
    res = requests.post(url, headers=headers, json=payload, stream=True)
    if res.status_code != 200:
        print("Error:", res.status_code, res.text)
        return None
    client = sseclient.SSEClient(res)
    for event in client.events():
        if event.event == "message":
            return json.loads(event.data)

# Initialize sequence
init_payload = {
    "jsonrpc": "2.0",
    "id": 1,
    "method": "initialize",
    "params": {
        "protocolVersion": "2024-11-05",
        "capabilities": {},
        "clientInfo": {"name": "cli", "version": "1.0"}
    }
}
send_req(init_payload)

init_notif = {
    "jsonrpc": "2.0",
    "method": "notifications/initialized"
}
requests.post(url, headers=headers, json=init_notif)

def call_tool(name, args):
    payload = {
        "jsonrpc": "2.0",
        "id": 2,
        "method": "tools/call",
        "params": {
            "name": name,
            "arguments": args
        }
    }
    return send_req(payload)

if __name__ == "__main__":
    if len(sys.argv) > 1:
        tool = sys.argv[1]
        args = json.loads(sys.argv[2]) if len(sys.argv) > 2 else {}
        print(json.dumps(call_tool(tool, args), indent=2))
